// ---------------------------------------------------------------------------
// Think-Block Token Patterns
// Gemma 4 uses: <|channel>thought … <channel|>
// ---------------------------------------------------------------------------

const THINK_START_REGEX = /<\|channel>thought/i;
const THINK_END_REGEX   = /<channel\|>/i;

// ---------------------------------------------------------------------------
// Wails Runtime Readiness
// ---------------------------------------------------------------------------

let wailsReady = false;
let wailsWaitLogCount = 0;

window.ICONS = ICONS;
window.pendingNarratorEvents = [];

function checkWailsReady() {
    const hasBindings = window.wails && window.wails._bindings;
    const hasGoBridge = window.go && window.go.main && window.go.main.App;

    if (hasBindings || hasGoBridge) {
        wailsReady = true;
        console.log('Wails runtime is ready');
    } else {
        if (wailsWaitLogCount < 5 || wailsWaitLogCount % 25 === 0) {
            console.log('Waiting for Wails runtime...');
        }
        wailsWaitLogCount += 1;
        setTimeout(checkWailsReady, 100);
    }
}

checkWailsReady();
